import{_ as a,o as t,c as s,ae as i}from"./chunks/framework.BThPlfjz.js";const m=JSON.parse('{"title":"Gateway Claims Ledger","description":"","frontmatter":{},"headers":[],"relativePath":"GatewayClaimsLedger.md","filePath":"GatewayClaimsLedger.md"}'),n={name:"GatewayClaimsLedger.md"};function o(l,e,r,d,p,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="gateway-claims-ledger" tabindex="-1">Gateway Claims Ledger <a class="header-anchor" href="#gateway-claims-ledger" aria-label="Permalink to &quot;Gateway Claims Ledger&quot;">​</a></h1><p><strong>Status: Partially built (2026-08-28).</strong> <code>GatewayClaimsManager</code> mutations now write the semantic ledger first and then materialize <code>gateway-claims.json</code> for nginx Lua. This note records the remaining split-brain in gateway authorization and the intended closure path. It mirrors the shape of <a href="./DomainStoreSplitBrain.html">DomainStoreSplitBrain.md</a>, but for <code>gateway-claims.json</code>.</p><hr><h2 id="the-model" tabindex="-1">The model <a class="header-anchor" href="#the-model" aria-label="Permalink to &quot;The model&quot;">​</a></h2><p>Netget runs over a designated <code>.me</code> namespace. The host is only the surface that accepted the connection; the namespace is the semantic context where durable paths live.</p><p>That means gateway authorization should be rooted in the same monad namespace that netget already uses for domain records:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NETGET_MONAD_NAMESPACE</span></span>
<span class="line"><span>  -&gt; xConfig.mainServerName</span></span>
<span class="line"><span>  -&gt; local.cleaker</span></span></code></pre></div><p><code>seed</code> and <code>namespace</code> stay separate:</p><ul><li><code>seed</code> is the gateway monad&#39;s cryptographic identity.</li><li><code>namespace</code> is the semantic context where writes land.</li></ul><p><code>GatewayClaimsManager</code> should not need its own namespace resolver. If it writes to netget&#39;s own monad through <code>monadHttpClient.ts</code>, the monad process already decides the namespace because it was started with <code>getGatewayRootNamespace()</code>.</p><hr><h2 id="the-gap" tabindex="-1">The gap <a class="header-anchor" href="#the-gap" aria-label="Permalink to &quot;The gap&quot;">​</a></h2><p>Historically, <code>GatewayClaimsManager.ts</code> treated the local JSON snapshot as the real source of truth:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.get/runtime/gateway-claims.json</span></span>
<span class="line"><span>~/.get/runtime/gateway-claims.version</span></span></code></pre></div><p>That JSON file is important and should stay, because nginx Lua reads it on the hot path for <code>X-Me-Proof</code> verification and scope lookup. Lua needs a local, synchronous, cheap materialized view.</p><p>The problem was that the JSON was not only a materialized view. It was the authoritative store. The mutation methods:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bootstrapOwner()</span></span>
<span class="line"><span>grantAdmin()</span></span>
<span class="line"><span>revokeAdmin()</span></span>
<span class="line"><span>transferOwner()</span></span></code></pre></div><p>mutated the JSON directly and never wrote to <code>.me</code> semantic memory. That made <code>gateway-claims.json</code> a second ledger parallel to the kernel.</p><p>The <code>GatewayClaimsManager</code> path is now corrected: those four methods write <code>netget.*</code> semantic paths first and then refresh the local snapshot from that ledger. The remaining split-brain is any legacy writer that still updates <code>gateway-claims.json</code> directly, especially Lua handlers such as <code>claim_identity.lua</code>.</p><p>This is the same class of failure that the domain store migration closed: a local file exists for speed, but it must not be the durable source of truth.</p><hr><h2 id="target-paths" tabindex="-1">Target paths <a class="header-anchor" href="#target-paths" aria-label="Permalink to &quot;Target paths&quot;">​</a></h2><p>Gateway authorization should live under netget&#39;s namespace as ordinary semantic paths:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>netget.owner.identityHash       -&gt; identityHash</span></span>
<span class="line"><span>netget.owner.username           -&gt; username</span></span>
<span class="line"><span>netget.admins.&lt;identityHash&gt;    -&gt; true</span></span>
<span class="line"><span>netget.grants.&lt;identityHash&gt;    -&gt; GatewayScope[]</span></span>
<span class="line"><span>netget.pubkeys.&lt;identityHash&gt;   -&gt; Ed25519 public key</span></span>
<span class="line"><span>netget.usernames.&lt;identityHash&gt; -&gt; username</span></span></code></pre></div><p>These paths are intentionally not rooted in a physical hostname. They belong to the designated namespace, for example <code>local.cleaker</code> locally or <code>cleaker.me</code> when the operator chooses a public namespace.</p><hr><h2 id="materialized-snapshot" tabindex="-1">Materialized snapshot <a class="header-anchor" href="#materialized-snapshot" aria-label="Permalink to &quot;Materialized snapshot&quot;">​</a></h2><p><code>gateway-claims.json</code> remains the file Lua consumes:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.me semantic memory -&gt; GatewayClaimsManager materialization -&gt; gateway-claims.json -&gt; Lua</span></span></code></pre></div><p>The JSON shape should remain flat:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;gatewayId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;suis-macbook-air.local&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;owner&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;admins&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {},</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;grants&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {},</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;pubkeys&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {},</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;usernames&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {},</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;updatedAt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1780000000000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Lua should not call the monad per request. The monad is the source; the JSON is the cache.</p><hr><h2 id="migration-plan" tabindex="-1">Migration plan <a class="header-anchor" href="#migration-plan" aria-label="Permalink to &quot;Migration plan&quot;">​</a></h2><ol><li>✅ Add semantic write helpers to <code>GatewayClaimsManager</code> using <code>writeToMonad()</code> and <code>readFromMonad()</code> from <code>src/kernel/monadHttpClient.ts</code>.</li><li>✅ Change the four mutation methods so they first update the semantic ledger, then regenerate and flush the local JSON snapshot.</li><li>✅ Add <code>migrateGatewayClaimsToMonad.ts</code> to import an existing <code>gateway-claims.json</code> into the semantic ledger once.</li><li>✅ Keep all read-side Lua behavior pointed at the JSON snapshot.</li><li>✅ Add tests proving both layers stay aligned for <code>GatewayClaimsManager</code>.</li><li>🔲 Move or retire legacy direct JSON writers (<code>claim_identity.lua</code>, <code>/api/v1/commit</code>, and other unauthenticated semantic commit paths) so every external write is attributable to a verified caller.</li></ol><p>The synchronous read API is preserved. The mutation API is now async because monad writes are HTTP calls.</p><hr><h2 id="required-tests" tabindex="-1">Required tests <a class="header-anchor" href="#required-tests" aria-label="Permalink to &quot;Required tests&quot;">​</a></h2><p>The migration should not be considered closed until these pass:</p><ul><li>Bootstrap writes <code>netget.owner.identityHash</code>, <code>netget.admins.&lt;owner&gt;</code>, <code>netget.grants.&lt;owner&gt;</code>, and the JSON snapshot.</li><li><code>grantAdmin()</code> writes semantic memory and updates the JSON snapshot.</li><li><code>revokeAdmin()</code> tombstones the semantic admin/grant/pubkey/username paths and removes them from the JSON snapshot.</li><li>The owner cannot be revoked.</li><li><code>transferOwner()</code> changes <code>netget.owner.identityHash</code> without deleting the previous owner&#39;s admin grant.</li><li>A regenerated snapshot from semantic memory matches the current JSON shape.</li><li>Lua-visible auth still reads only <code>gateway-claims.json</code>.</li><li><code>reset()</code> tombstones owner/admin/grant/pubkey/username paths instead of only deleting the local JSON snapshot.</li></ul><p>The important invariant:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>semantic ledger is authoritative</span></span>
<span class="line"><span>gateway-claims.json is materialized</span></span>
<span class="line"><span>Lua consumes the materialized view</span></span></code></pre></div><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./DomainStoreSplitBrain.html">DomainStoreSplitBrain.md</a> - the already-fixed version of this same split-brain pattern for domain routing.</li><li><a href="./GatewayCapabilityModel.html">GatewayCapabilityModel.md</a> - signed capability checks that currently consume <code>gateway-claims.json</code>.</li><li><a href="./EncryptedAudienceCapabilityTests.html">EncryptedAudienceCapabilityTests.md</a> - the live proof that <code>A</code>, auth, and <code>C</code> stay separate for gateway writes.</li></ul>`,45)])])}const g=a(n,[["render",o]]);export{m as __pageData,g as default};
